import hmac
import hashlib
import base64
import json
import time
import os
import re
from typing import Optional, Dict, Any
from dataclasses import dataclass, field


@dataclass
class RateLimitEntry:
    tokens: float
    last_refill: float
    violations: int = 0


class SecureTokenService:
    """Production token service with rate limiting and signature verification."""

    def __init__(self, secret_key: bytes, issuer: str = "auth-service",
                 max_clock_skew: int = 30, token_lifetime: int = 3600):
        self._secret = secret_key
        self._issuer = issuer
        self._max_skew = max_clock_skew
        self._lifetime = token_lifetime
        self._revoked: set = set()
        self._rate_limits: Dict[str, RateLimitEntry] = {}
        self._bucket_capacity = 10
        self._refill_rate = 1.0  # tokens per second

    def _b64url_encode(self, data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    def _b64url_decode(self, s: str) -> bytes:
        # Add padding
        padding = 4 - len(s) % 4
        if padding != 4:
            s += '=' * padding
        return base64.urlsafe_b64decode(s)

    def _compute_signature(self, header_b64: str, payload_b64: str) -> str:
        signing_input = f"{header_b64}.{payload_b64}".encode('utf-8')
        sig = hmac.new(self._secret, signing_input, hashlib.sha256).digest()
        return self._b64url_encode(sig)

    def _check_rate_limit(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self._rate_limits:
            self._rate_limits[client_id] = RateLimitEntry(
                tokens=self._bucket_capacity, last_refill=now
            )

        entry = self._rate_limits[client_id]
        elapsed = now - entry.last_refill
        entry.tokens = min(self._bucket_capacity, 
                          entry.tokens + elapsed * self._refill_rate)
        entry.last_refill = now

        if entry.tokens >= 1.0:
            entry.tokens -= 1.0
            return True
        else:
            entry.violations += 1
            return False

    def create_token(self, subject: str, claims: Dict[str, Any] = None,
                     scopes: list = None) -> str:
        now = int(time.time())
        header = {"alg": "HS256", "typ": "JWT"}
        payload = {
            "sub": subject,
            "iss": self._issuer,
            "iat": now,
            "exp": now + self._lifetime,
            "jti": os.urandom(16).hex()
        }
        if claims:
            # Don't allow overriding critical claims
            safe_claims = {k: v for k, v in claims.items() 
                          if k not in ('iss', 'iat', 'exp', 'jti', 'sub')}
            payload.update(safe_claims)
        if scopes:
            payload["scope"] = scopes

        header_b64 = self._b64url_encode(json.dumps(header, separators=(',', ':')).encode())
        payload_b64 = self._b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
        signature = self._compute_signature(header_b64, payload_b64)

        return f"{header_b64}.{payload_b64}.{signature}"

    def verify_token(self, token: str, client_id: str = "anonymous") -> Optional[Dict[str, Any]]:
        """Verify token with rate limiting, revocation check, and signature validation."""
        if not self._check_rate_limit(client_id):
            return None

        if not isinstance(token, str):
            return None

        parts = token.split('.')
        if len(parts) != 3:
            return None

        header_b64, payload_b64, signature_b64 = parts

        # Validate header
        try:
            header = json.loads(self._b64url_decode(header_b64))
        except (json.JSONDecodeError, Exception):
            return None

        if header.get('alg') != 'HS256':
            return None

        # Verify signature
        expected_sig = self._compute_signature(header_b64, payload_b64)

        # Decode both signatures for comparison
        try:
            sig_bytes = self._b64url_decode(signature_b64)
            expected_bytes = self._b64url_decode(expected_sig)
        except Exception:
            return None

        # Use length check before comparison to avoid processing invalid tokens
        if len(sig_bytes) != len(expected_bytes):
            return None

        # Constant-time comparison on decoded bytes
        if not hmac.compare_digest(sig_bytes, expected_bytes):
            return None

        # Parse and validate payload
        try:
            payload = json.loads(self._b64url_decode(payload_b64))
        except (json.JSONDecodeError, Exception):
            return None

        # Check revocation
        jti = payload.get('jti')
        if jti and jti in self._revoked:
            return None

        # Validate temporal claims
        now = time.time()
        exp = payload.get('exp')
        iat = payload.get('iat')

        if exp is not None:
            if now > exp + self._max_skew:
                return None

        if iat is not None:
            if iat > now + self._max_skew:
                return None

        # Validate issuer
        if payload.get('iss') != self._issuer:
            return None

        return payload

    def revoke_token(self, jti: str) -> None:
        if isinstance(jti, str) and len(jti) <= 64:
            self._revoked.add(jti)

    def check_scope(self, payload: Dict[str, Any], required_scope: str) -> bool:
        """Check if token has required scope."""
        scopes = payload.get('scope', [])
        if not isinstance(scopes, list):
            return False
        return required_scope in scopes
